    ('frontend/src/pages/Backtest.jsx', 'fvgLots, fvgLotSize, fvgDteMult, fvgMode,   // ── FVG_V1_20260916 ── STALE-CLOSURE RULE: buildConfig reads every one of these.\n', 'fvgLots, fvgLotSize, fvgDteMult, fvgMode,   // ── FVG_V1_20260916 ── STALE-CLOSURE RULE: buildConfig reads every one of these.\n    emcSpotTf, emcOptTf, emcFast, emcSlow, emcOptCheck, emcDir, emcSelMin, emcSelMax, emcSelPick, emcFill, emcOptMinBars, emcOptWarm, emcSl, emcTp, emcTrailOn, emcTrailTrig, emcTrailGap, emcXover, emcCutoff, emcEod, emcMaxDay, emcMaxLoss, emcLots, emcLotSize, emcSkipExpiry, emcDteMult,   // ── EMC_V1_20261011 ── STALE-CLOSURE RULE: buildConfig reads every one of these.\n', 1),
    ('frontend/src/pages/Backtest.jsx', 'summary?.diag_stfc || summary?.diag_fvg);', 'summary?.diag_stfc || summary?.diag_fvg || summary?.diag_emc);   // ── EMC_V1_20261011 ──', 1),
    ('frontend/src/pages/Backtest.jsx', '          { id: "FVG_V1", label: "FVG V1", sub: "FVG retest" },   // ── FVG_V1_20260916 ──\n', '          { id: "FVG_V1", label: "FVG V1", sub: "FVG retest" },   // ── FVG_V1_20260916 ──\n          { id: "EMC_V1", label: "EMC V1", sub: "EMA 9/21 spot→option" },   // ── EMC_V1_20261011 ──\n', 1),
